begin;
alter table public.organization_memberships add column status text not null default'active'check(status in('active','suspended'));
create function public.guardian_dashboard(p_learner uuid default null)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare selected uuid;org uuid;result jsonb;begin if p_learner is not null then select g.learner_id,g.organization_id into selected,org from public.guardian_relationships g where g.guardian_id=auth.uid()and g.learner_id=p_learner and g.status='active';if selected is null then raise exception'guardian relationship unavailable'using errcode='42501';end if;end if;select jsonb_build_object('learners',coalesce((select jsonb_agg(jsonb_build_object('learnerId',g.learner_id,'organizationId',g.organization_id))from public.guardian_relationships g where g.guardian_id=auth.uid()and g.status='active'),'[]'::jsonb),'selectedLearnerId',selected,'assignments',case when selected is null then'[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('assignmentId',a.id,'state',a.state,'availableFrom',a.available_from,'dueAt',a.due_at,'sessionState',s.state,'progress',s.progress))from public.class_enrollments e join public.assignments a on a.class_id=e.class_id left join public.learning_sessions s on s.assignment_id=a.id and s.learner_id=e.learner_id where e.learner_id=selected and e.status='active'and a.organization_id=org),'[]'::jsonb)end,'mastery',case when selected is null then'[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('objectiveId',d.objective_id,'calculatedState',d.new_state,'effectiveState',coalesce(o.override_state,d.new_state),'updatedAt',coalesce(o.created_at,d.created_at)))from public.mastery_decisions d left join lateral(select m.override_state,m.created_at from public.mastery_overrides m where m.mastery_decision_id=d.id and m.status='active'order by m.created_at desc limit 1)o on true where d.learner_id=selected and d.organization_id=org),'[]'::jsonb)end,'recommendations',case when selected is null then'[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('recommendationId',r.id,'kind',r.kind,'status',r.status,'reason',r.reason,'createdAt',r.created_at))from public.learning_recommendations r where r.learner_id=selected and r.organization_id=org and r.status<>'dismissed'),'[]'::jsonb)end,'remediation',case when selected is null then'[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('remediationId',r.id,'status',r.status,'availableFrom',r.available_from,'dueAt',r.due_at,'completedAt',r.completed_at))from public.remediation_assignments r where r.learner_id=selected and r.organization_id=org),'[]'::jsonb)end,'guidance',case when selected is null then'[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('objectiveId',n.objective_id,'guidance',n.note,'createdAt',n.created_at))from public.intervention_notes n where n.learner_id=selected and n.organization_id=org and n.guardian_visible),'[]'::jsonb)end)into result;return result;end$$;
create function public.administrator_dashboard(p_limit integer default 50)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare org uuid;result jsonb;begin if p_limit<1 or p_limit>100 then raise exception'limit must be between 1 and 100';end if;select m.organization_id into org from public.organization_memberships m where m.user_id=auth.uid()and m.role in('administrator','platform_administrator')and m.status='active'order by m.created_at limit 1;if org is null then raise exception'administrator authorization required'using errcode='42501';end if;select jsonb_build_object('organizationId',org,'counts',jsonb_build_object('classes',(select count(*)from public.classes where organization_id=org),'enrollments',(select count(*)from public.class_enrollments where organization_id=org),'assignments',(select count(*)from public.assignments where organization_id=org),'sessions',(select count(*)from public.learning_sessions where organization_id=org),'attempts',(select count(*)from public.assessment_attempts where organization_id=org),'scores',(select count(*)from public.assessment_scores where organization_id=org),'overrides',(select count(*)from public.mastery_overrides where organization_id=org),'remediations',(select count(*)from public.remediation_assignments where organization_id=org)),'classes',coalesce((select jsonb_agg(x.row)from(select jsonb_build_object('classId',c.id,'stableId',c.stable_id,'name',c.name,'teacherId',c.teacher_id,'enrollmentCount',(select count(*)from public.class_enrollments e where e.class_id=c.id))row from public.classes c where c.organization_id=org order by c.created_at desc limit p_limit)x),'[]'::jsonb),'assignments',coalesce((select jsonb_agg(x.row)from(select jsonb_build_object('assignmentId',a.id,'classId',a.class_id,'state',a.state,'availableFrom',a.available_from,'dueAt',a.due_at,'attemptLimit',a.attempt_limit)row from public.assignments a where a.organization_id=org order by a.created_at desc limit p_limit)x),'[]'::jsonb),'workflow',jsonb_build_object('pendingHumanScores',(select count(*)from public.assessment_attempts where organization_id=org and state='pending_human_scoring'),'activeOverrides',(select count(*)from public.mastery_overrides where organization_id=org and status='active'),'openRecommendations',(select count(*)from public.learning_recommendations where organization_id=org and status in('available','accepted','continued','no_content')),'pendingOutbox',(select count(*)from public.learning_outbox where organization_id=org and processed_at is null),'failedOutbox',(select count(*)from public.learning_outbox where organization_id=org and attempts>0 and processed_at is null)),'audit',coalesce((select jsonb_agg(x.row)from(select jsonb_build_object('eventId',e.id,'eventType',e.event_type,'aggregateType',e.aggregate_type,'aggregateId',e.aggregate_id,'occurredAt',e.occurred_at)row from public.audit_events e where e.organization_id=org order by e.occurred_at desc limit p_limit)x),'[]'::jsonb))into result;return result;end$$;
revoke all on function public.guardian_dashboard(uuid),public.administrator_dashboard(integer)from public;grant execute on function public.guardian_dashboard(uuid),public.administrator_dashboard(integer)to authenticated;
commit;
